FUNCTION_BLOCK FB
VAR_INPUT
    mode            : INT;
    resetBtn        : BOOL;
    scanSeconds     : REAL;
    tempSP          : REAL;
    tempPV          : REAL;
    flowPV          : REAL;
    manualFlowSP    : REAL;
    manualValve     : REAL;
END_VAR
VAR_OUTPUT
    flowSP          : REAL;
    valveCommand    : REAL;
    fault           : BOOL;
    normalMode      : BOOL;
END_VAR
VAR
    prevMode            : INT;
    prevModeValid       : BOOL;
    prevResetBtn        : BOOL;
    iT                  : REAL;
    iF                  : REAL;
    prevValveCommand    : REAL;
    prevFlowSP          : REAL;
    modeChanged         : BOOL;
END_VAR
VAR CONSTANT
    KpT     : REAL := 1.0;
    KpF     : REAL := 2.0;
    KiT     : REAL := 0.2;
    KiF     : REAL := 0.5;
END_VAR

// 模式变化检测
modeChanged := prevModeValid AND (mode <> prevMode);

// 故障检测
fault := (mode < 0) OR (mode > 2) OR (scanSeconds <= 0.0) OR (scanSeconds > 10.0);

// 初始化/复位上升沿/故障处理
IF (NOT prevModeValid) OR (resetBtn AND NOT prevResetBtn) OR fault THEN
    flowSP := manualFlowSP;
    valveCommand := manualValve;
    iT := manualFlowSP - KpT * (tempSP - tempPV);
    iF := manualValve - KpF * (manualFlowSP - flowPV);
    prevValveCommand := manualValve;
    prevFlowSP := manualFlowSP;
    prevMode := mode;
    prevModeValid := TRUE;
    prevResetBtn := resetBtn;
    normalMode := FALSE;

// 模式切换处理
ELSIF modeChanged THEN
    // 阀位保持上一拍
    valveCommand := prevValveCommand;

    // flowSP保持或跟随
    IF mode = 2 THEN
        flowSP := prevFlowSP;
    ELSE
        flowSP := manualFlowSP;
    END_IF

    // 重算积分项
    iT := flowSP - KpT * (tempSP - tempPV);
    iF := valveCommand - KpF * (flowSP - flowPV);

    prevMode := mode;
    prevResetBtn := resetBtn;
    normalMode := FALSE;

// 正常运算拍
ELSE
    normalMode := TRUE;

    // mode=0: 全手动
    IF mode = 0 THEN
        flowSP := manualFlowSP;
        valveCommand := manualValve;
        iT := flowSP - KpT * (tempSP - tempPV);
        iF := valveCommand - KpF * (flowSP - flowPV);

    // mode=1: 外环手动/内环自动
    ELSIF mode = 1 THEN
        flowSP := manualFlowSP;
        iT := flowSP - KpT * (tempSP - tempPV);

        VAR eF : REAL;
        END_VAR
        eF := flowSP - flowPV;
        iF := iF + KiF * eF * scanSeconds;
        valveCommand := LIMIT(0.0, KpF * eF + iF, 100.0);
        iF := valveCommand - KpF * eF;

    // mode=2: 串级全自动
    ELSIF mode = 2 THEN
        VAR eT : REAL;
        VAR eF : REAL;
        END_VAR
        eT := tempSP - tempPV;
        iT := iT + KiT * eT * scanSeconds;
        flowSP := LIMIT(0.0, KpT * eT + iT, 50.0);
        iT := flowSP - KpT * eT;

        eF := flowSP - flowPV;
        iF := iF + KiF * eF * scanSeconds;
        valveCommand := LIMIT(0.0, KpF * eF + iF, 100.0);
        iF := valveCommand - KpF * eF;
    END_IF;

    prevMode := mode;
    prevResetBtn := resetBtn;
END_IF;

// 更新历史记录
prevValveCommand := valveCommand;
prevFlowSP := flowSP;
